/** Bounded native React status rendering probe; all overrides are test-only and restored. */
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const root='/Users/zsviczian/GitHub/kplex',out='/private/tmp/kplex-pr82-native';
mkdirSync(out,{recursive:false});const driver=readFileSync(new URL(import.meta.url));writeFileSync(out+'/driver-source.mjs',driver);
const report={status:'running',startedAt:new Date().toISOString(),driverSha256:createHash('sha256').update(driver).digest('hex'),limitations:['Native production React with controlled test-only status/visibility/mode reads, not an actual indexing stall or timing benchmark.','No physical-device touch or real hardware keyboard acceptance.']};
/** Run one explicit-vault native call and preserve its actual errors. */
function cli(command,...args){const r=spawnSync('/usr/local/bin/obsidian',['vault=kplex-test-small',command,...args],{encoding:'utf8',timeout:30000,maxBuffer:4*1024*1024});if(r.error||r.status!==0||/^Error:/m.test(r.stdout))throw r.error??Error(r.stderr||r.stdout);return r.stdout.trim();}
/** Parse a detached response from the native renderer. */
function evaluate(code){return JSON.parse(cli('eval',`code=${code}`).replace(/^=>\s*/,''));}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
/** Own exact method descriptors and restore the React view without leaving production hooks. */
function install(){
 const remote=require('@electron/remote'),win=remote.getCurrentWindow(),p=app.plugins.plugins['k-plex'];
 if(!p?.actionManager||window.__kplexStatusProbe)throw Error('Loaded plugin and no controller required');
 if(remote.powerMonitor.getSystemIdleState(10)==='locked')throw Error('Unlocked session required');
 const leaf=app.workspace.getLeavesOfType('k-plex-react-view').find(l=>l.view.contentEl.ownerDocument===document&&p.isKplexLeafVisible(l));
 if(!leaf)throw Error('Visible main-window Plex leaf required');
 const c=window.__kplexStatusProbe={done:false,scenarios:[],originalStatus:p.getIndexStatus(),originalMode:p.index.isOnDemandMode(),listenersBefore:p.indexStatusListeners.size,visibilityBefore:p.kplexVisibilityListeners.size,overrides:[]};
 /** Fail at the actual bounded observation rather than treating a skip as pass. */
 const check=(ok,message)=>{if(!ok)throw Error(message);};
 /** Poll real mounted DOM within the existing local readiness deadline. */
 const until=async(predicate,message,ms=15000)=>{const end=Date.now()+ms;while(!predicate()){check(Date.now()<end,message);await new Promise(r=>window.setTimeout(r,25));}};
 const passed=(id,details={})=>c.scenarios.push({id,status:'passed',...details});
 const indicator=()=>leaf.view.contentEl.querySelector('.kplex-index-status');
 const details=()=>[...document.querySelectorAll('.kplex-index-status-details')].find(e=>e.getClientRects().length);
 /** Retain descriptors so prototype methods are not replaced by permanent own properties. */
 const override=(owner,key,value)=>{c.overrides.push({owner,key,descriptor:Object.getOwnPropertyDescriptor(owner,key)});owner[key]=value;};
 c.cleanup=async()=>{
  for(const item of c.overrides.splice(0).reverse()){if(item.descriptor)Object.defineProperty(item.owner,item.key,item.descriptor);else delete item.owner[item.key];}
  leaf.view.renderReact();await leaf.view.waitUntilReady();
  await until(()=>indicator()?.getAttribute('aria-label')===p.getIndexStatus().label,'Original live status did not restore');
  await p.actionPreferenceQueue;await p.settingsWriteQueue;
  check(p.indexStatusListeners.size===c.listenersBefore&&p.kplexVisibilityListeners.size===c.visibilityBefore,'React root replacement leaked status listeners');
  check(p.index.isOnDemandMode()===c.originalMode,'Original indexing mode read did not restore');
  c.cleaned=true;
 };
 c.task=(async()=>{
  remote.app.show();remote.app.focus({steal:true});win.show();win.focus();win.webContents.focus();
  await until(()=>win.isFocused()&&document.hasFocus()&&!document.hidden,'Native foreground unavailable',5000);
  check(c.originalStatus.upToDate,'Start from actual local graph readiness');
  const pending={upToDate:false,phase:'updating',label:'Preparing local graph',indexedFiles:4,totalFiles:73};
  const ready={...pending,upToDate:true,phase:'ready',label:'Local graph ready'};
  let current=pending,visible=false,mode=c.originalMode,attachRace=true;
  const getStatus=p.getIndexStatus,visibility=p.isKplexLeafVisible,subscribe=p.subscribeIndexStatus;
  override(p,'getIndexStatus',()=>current);
  override(p,'isKplexLeafVisible',function(target){return target===leaf?visible:visibility.call(this,target);});
  override(p,'subscribeIndexStatus',function(listener){const release=subscribe.call(this,listener);if(attachRace){attachRace=false;current=ready;c.mountRaceObserved=true;}return release;});
  override(p.index,'isOnDemandMode',()=>mode);
  leaf.view.renderReact();await leaf.view.waitUntilReady();
  await until(()=>indicator()?.classList.contains('is-ready')&&indicator().getAttribute('aria-label')===ready.label,'Mount-to-effect readiness remained stale');
  check(c.mountRaceObserved,'Controlled readiness transition did not occur at subscription');
  passed('mount-effect-race-catches-ready',{notificationsEmitted:0,indicator:indicator().getAttribute('aria-label')});
  visible=true;current=pending;for(const listener of p.kplexVisibilityListeners)listener();
  await until(()=>indicator()?.classList.contains('is-updating')&&indicator().getAttribute('aria-label')===pending.label,'Reveal did not catch current preparing status');
  passed('reveal-catches-preparing');
  const node=indicator();node.focus();await until(()=>details(),'Status details did not open on focus');
  check(mode===true,'Small disposable vault should use actual on-demand mode');
  const ratio=p.translator('index.filesIndexed',{indexed:4,total:73});
  check(!details().textContent.includes(ratio)&&details().textContent.includes(pending.label),'On-demand ratio still shown or label lost');
  passed('on-demand-details-hide-whole-vault-ratio',{text:details().textContent,ratio});
  mode=false;current={...pending,indexedFiles:5};for(const listener of p.indexStatusListeners)listener();
  const eagerRatio=p.translator('index.filesIndexed',{indexed:5,total:73});
  await until(()=>details()?.textContent.includes(eagerRatio),'Full-index progress ratio disappeared');
  passed('full-index-details-preserve-ratio',{text:details().textContent});
  mode=true;visible=false;current=ready;for(const listener of p.indexStatusListeners)listener();
  await until(()=>indicator()?.classList.contains('is-ready')&&indicator().getAttribute('aria-label')===ready.label,'Hidden geometry prevented terminal readiness');
  passed('hidden-terminal-readiness-clears-stale-status');
  current={...pending,label:'Controlled hidden progress'};for(const listener of p.indexStatusListeners)listener();await new Promise(r=>window.setTimeout(r,100));
  check(indicator().getAttribute('aria-label')===ready.label,'Hidden intermediate progress rerendered');
  passed('hidden-intermediate-progress-skipped');
  visible=true;for(const listener of p.kplexVisibilityListeners)listener();
  await until(()=>indicator()?.getAttribute('aria-label')===current.label,'Revealed status did not catch up');
  passed('reveal-after-hidden-progress-catches-current');
 })().then(()=>{c.done=true;},error=>{c.error=String(error);c.done=true;});
 return JSON.stringify({installed:true});
}
let installed=false;
try{
 assert.equal(cli('vault','info=path').replace(/^path\s+/,''),'/Users/zsviczian/Obsidian/kplex-test-small');
 report.artifacts={};for(const name of ['main.js','styles.css','manifest.json']){const hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex');report.artifacts[name]=hash(root+'/dist/'+name);assert.equal(hash('/Users/zsviczian/Obsidian/kplex-test-small/.obsidian/plugins/k-plex/'+name),report.artifacts[name]);}
 const readinessDeadline=Date.now()+30000;
 do{report.liveReadiness=evaluate('JSON.stringify(app.plugins.plugins["k-plex"].getIndexStatus())');if(report.liveReadiness.upToDate)break;if(Date.now()>readinessDeadline)throw Error('Actual local graph did not become ready before controlled probe');await delay(500);}while(true);
 cli('dev:errors','clear');evaluate(`(${install.toString()})()`);installed=true;
 let result;const end=Date.now()+60000;
 do{await delay(300);result=evaluate('JSON.stringify({done:window.__kplexStatusProbe.done,error:window.__kplexStatusProbe.error,scenarios:window.__kplexStatusProbe.scenarios,originalStatus:window.__kplexStatusProbe.originalStatus})');if(Date.now()>end)throw Error('Status probe deadline');}while(!result.done);
 Object.assign(report,result);if(result.error)throw Error(result.error);
 report.status='passed';
}catch(error){report.status='failed';report.error=String(error);}
finally{
 if(installed){try{report.cleanup=evaluate('(async()=>{const c=window.__kplexStatusProbe;await c.task;await c.cleanup();const result={cleaned:c.cleaned,scenarios:c.scenarios,overridesRemaining:c.overrides.length,originalStatus:c.originalStatus,restoredStatus:app.plugins.plugins["k-plex"].getIndexStatus()};delete window.__kplexStatusProbe;return JSON.stringify(result)})()');if(!report.cleanup.cleaned)throw Error('Cleanup incomplete');}catch(error){report.status='failed';report.cleanupError=String(error);}}
 try{report.nativeErrors=cli('dev:errors');assert.match(report.nativeErrors,/^No errors captured\.?$/i);}catch(error){report.status='failed';report.nativeErrorFailure=String(error);}
 report.completedAt=new Date().toISOString();writeFileSync(out+'/report.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));
}
if(report.status!=='passed')process.exitCode=1;
